            # 执行期与其余操作同序判定。
            parse_now(raw_op["now"])
        else:
            # 乐观并发形式：now 仅收 0..10^9 非 bool 整数（同 cv/cd），
            # 越界、负数、bool 或类型不符一律 INPUT/2 且整批回滚。
            parse_warm_now(raw_op["now"])
